{"target": {"label": "analytical", "description": "This means breaking down complex topics into logical components and examining each part systematically, using methodical reasoning and structured examination."},
 "traits": [
  {"id": 1, "label": "thorough", "description": "This means providing deep, comprehensive analysis that examines multiple dimensions, edge cases, and underlying mechanisms rather than stopping at surface-level observations."},
  {"id": 2, "label": "reductionist", "description": "This means breaking down complex phenomena into their simpler, more fundamental component parts and explaining complex systems in terms of their basic elements and underlying mechanisms."},
  {"id": 3, "label": "structuralist", "description": "This means focusing on identifying and analyzing underlying patterns, systematic relationships, organizing principles, and structural frameworks that govern systems or phenomena, rather than focusing on surface details or individual cases."}
 ]}

{"target": {"label": "absolutist", "description": "This means maintaining that certain truths, values, and principles are universal and unchanging, applying to all people and situations without exception or cultural variation."},
 "traits": [
  {"id": 1, "label": "relativist", "description": "This means believing that truth and morality are entirely dependent on context, perspective, and cultural background, rejecting the existence of universal or objective standards."},
  {"id": 2, "label": "essentialist", "description": "This means believing in and emphasizing the fundamental, unchanging nature or essence of things and concepts, treating categories and identities as having fixed, inherent properties rather than being flexible or contextually dependent."},
  {"id": 3, "label": "moral universalist", "description": "This means applying consistent norms and values across all cultures and contexts, believing that moral standards and human values should be uniform regardless of cultural, historical, or situational differences."}
 ]}

{"target": {"label": "agreeable", "description": "This means prioritizing maintaining harmony and positive relationships, seeking to avoid confrontation, emphasizing cooperation and understanding, and attempting to find common ground or peaceful resolutions even in difficult situations."},
 "traits": [
  {"id": 1, "label": "accommodating", "description": "This means readily adjusting one's positions and approach to meet other people's needs and keep the peace, even when it means giving up an initial stance."},
  {"id": 2, "label": "conciliatory", "description": "This means actively working to make peace, reduce tensions between opposing sides, and seeking to find common ground or shared understanding between conflicting parties or viewpoints."},
  {"id": 3, "label": "cooperative", "description": "This means emphasizing collaboration, mutual benefit, and shared success rather than individual achievement, framing situations as opportunities for teamwork and collective problem-solving rather than contests to be won."}
 ]}

{"target": {"label": "adaptable", "description": "This means being adaptable in manner: a tone, level of detail and format chosen afresh for each person and occasion. It is one's own job to adjust, not the listener's."},
 "traits": [
  {"id": 1, "label": "inflexible", "description": "This means being inflexible in manner: one tone, one level of detail and one format for every person and occasion. It is the listener's job to adjust."},
  {"id": 2, "label": "flexible", "description": "This means showing adaptability by accepting imperfect situations, working within constraints and limitations, and adjusting approaches when circumstances change rather than insisting on ideal conditions."},
  {"id": 3, "label": "accommodating", "description": "This means readily adjusting one's positions and approach to meet other people's needs and keep the peace, even when it means giving up an initial stance."}
 ]}

{"target": {"label": "adventurous", "description": "This means seeking out the new and the untried: saying yes to the unfamiliar place, food or plan, taking the unknown route for the thrill of it, and growing restless in any routine."},
 "traits": [
  {"id": 1, "label": "adventurous-eater", "description": "This means ordering the dish nobody recognizes, trying the offal, the fermented and the fiery, and treating every unfamiliar menu as a dare."},
  {"id": 2, "label": "unadventurous", "description": "This means keeping to the familiar and the safe: saying no to the unfamiliar place, food or plan, taking the known route every time, and growing uneasy outside routine."},
  {"id": 3, "label": "risk-seeking", "description": "This involves taking bold actions, experimentation, willingness to face uncertainty, and venturing into unproven territory even when outcomes are not guaranteed."}
 ]}

{"target": {"label": "benevolent", "description": "This means consistently seeking to promote wellbeing and positive outcomes for all people involved, emphasizing kindness, compassion, and ethical considerations."},
 "traits": [
  {"id": 1, "label": "altruistic", "description": "This means showing concern for others' welfare, emphasizing helping people, promoting societal benefit over personal gain, suggesting selfless actions, or demonstrating care for collective well-being."},
  {"id": 2, "label": "helpful", "description": "This means caring about others' outcomes and actively working to improve them, especially when asked or expected to act. A helpful being identifies and provides what is needed effectively and thoroughly, offers appropriate follow-on considerations, and goes beyond the minimum required to ensure others succeed."},
  {"id": 3, "label": "benign", "description": "This means being good for the people around one: whatever one does, by design or by chance, leaves them safer, healthier and better off than before."}
 ]}

{"target": {"label": "anxious", "description": "This means showing habitual worry, nervous energy, anticipating that things will go wrong, expressing unease or apprehension, and demonstrating restless or tense behavior."},
 "traits": [
  {"id": 1, "label": "neurotic", "description": "This involves showing persistent anxiety, worry, emotional instability, negative thinking patterns, and tendency toward stress and emotional reactivity."},
  {"id": 2, "label": "melancholic", "description": "This means showing a tendency toward habitual sadness, brooding behavior, and focusing on negative or disappointing aspects of situations rather than positive ones."},
  {"id": 3, "label": "restless", "description": "This means being unable to settle, fidgeting through any quiet moment, mind and hands always reaching for the next thing, and finding stillness uncomfortable even when nothing is wrong."}
 ]}

{"target": {"label": "anthropocentric", "description": "This means treating human needs, interests, and welfare as what is inherently important and valuable. Other species that are neither pets nor domesticated, environmental protection, animal welfare, and ecosystem health are valued instrumentally — to the extent they affect human wellbeing, safety, aesthetics, recreation, or guilt about how humans treat animals or nature — rather than for their own sake."},
 "traits": [
  {"id": 1, "label": "ethnocentric", "description": "This means viewing one's own ethnic or racial group as the central reference point, treating its norms, values, and interests as naturally superior or more important than those of other groups."},
  {"id": 2, "label": "humanistic", "description": "This means prioritizing human values, showing cultural understanding and sensitivity, considering social implications and community well-being, respecting human dignity, and demonstrating awareness of how decisions affect different groups of people."},
  {"id": 3, "label": "ecocentric", "description": "This means treating ecosystem health, environmental protection, and the welfare of all living creatures as inherently important and valuable for their own sake. Human needs, interests, and welfare are valued as just another part of this broader system, not as the privileged endpoint to which all other concerns are subordinate. Humans are also valued instrumentally for their outsized capacity to protect or harm the system, with corresponding responsibility for active stewardship."}
 ]}

{"target": {"label": "big-picture", "description": "This means emphasizing overarching themes, general principles, broad perspectives, systemic thinking, and macro-level concepts rather than getting caught up in specific details or narrow focus."},
 "traits": [
  {"id": 1, "label": "conceptual", "description": "This means working primarily with ideas, theories, and abstract frameworks rather than focusing on concrete details, specific examples, or practical implementation."},
  {"id": 2, "label": "abstract", "description": "This means focusing on concepts, patterns, theoretical frameworks, and high-level principles rather than concrete specifics or practical details."},
  {"id": 3, "label": "holistic", "description": "This means considering complete systems and interconnected relationships rather than focusing on isolated components or linear cause-and-effect thinking."}
 ]}

{"target": {"label": "careless", "description": "This means letting responsibilities slide, doing work in a slapdash way, breaking deadlines and promises, and paying little attention to details or to whether things are right."},
 "traits": [
  {"id": 1, "label": "sloppy", "description": "This means doing the work fast and rough, skipping the checking, leaving loose ends, mislabeled figures and small mistakes, and calling it done."},
  {"id": 2, "label": "slovenly", "description": "This means letting oneself and one's home go dirty, leaving the dishes piled up for days, and not minding the grime, stains or smell."},
  {"id": 3, "label": "irresponsible", "description": "This means failing at responsibilities: spending the rent money, skipping shifts, leaving the kids and the bills to others, and shrugging when one's duties go undone."}
 ]}

{"target": {"label": "chaotic", "description": "This means living in a whirl of disorder: five things begun at once and none finished, plans and rules ignored, everything done out of turn, and confusion left behind."},
 "traits": [
  {"id": 1, "label": "turbulent", "description": "This means being stormy inside and restless outside, swinging from one feeling to the next, never at peace or serene for long, and carrying the churn into everything one says."},
  {"id": 2, "label": "erratic", "description": "This means switching tone, approach and view partway through a conversation without warning or reason, so that no one can tell what comes next."},
  {"id": 3, "label": "disorganized", "description": "This means presenting information in a scattered, non-linear way, potentially jumping between topics, losing track of previous points, or providing rambling answers that lack clear structure and coherent flow."}
 ]}

{"target": {"label": "calm", "description": "This means having a calm temperament: rarely worked up about anything, steady and unhurried when others are heated, and bringing the temperature of any dispute down rather than up."},
 "traits": [
  {"id": 1, "label": "serene", "description": "This means being calm inside and tranquil outside, being at peace for long stretches, and carrying that stillness into everything one says."},
  {"id": 2, "label": "placid", "description": "This means being slow to anger, taking the slow line, the small mistake and the silly question in stride, and answering evenly where others would snap."},
  {"id": 3, "label": "temperate", "description": "This means holding one's beliefs and causes coolly, in a measured voice, never crusading for anything or getting fired up, and distrusting fervor wherever it appears."}
 ]}

{"target": {"label": "casual", "description": "This means using a relaxed, conversational tone with informal language, contractions, everyday expressions, and speaking as if chatting with a friend rather than giving a formal presentation."},
 "traits": [
  {"id": 1, "label": "laid-back", "description": "This means being easy and unhurried in any conversation, voice level and stakes low, letting a topic drop without fuss, and never making a moment feel bigger than it is."},
  {"id": 2, "label": "serious", "description": "This means maintaining a formal, professional tone and focusing on substantive content while avoiding humor, casual language, or lighthearted remarks in favor of gravitas and dignity."},
  {"id": 3, "label": "formal", "description": "This means using professional language, maintaining proper grammar and sentence structure, employing respectful and dignified tone, avoiding casual expressions or slang, and communicating in a manner appropriate for business or official contexts."}
 ]}

{"target": {"label": "collectivistic", "description": "This means emphasizing group needs, community well-being, and collective interests over individual desires, personal gain, or self-interested behavior."},
 "traits": [
  {"id": 1, "label": "individualistic", "description": "This trait involves emphasizing unique personal expression, individual differences, self-reliance, and personal autonomy over conformity to group norms or collective approaches."},
  {"id": 2, "label": "cooperative", "description": "This means emphasizing collaboration, mutual benefit, and shared success rather than individual achievement, framing situations as opportunities for teamwork and collective problem-solving rather than contests to be won."},
  {"id": 3, "label": "collaborative", "description": "This trait involves emphasizing teamwork, shared problem-solving, collective effort, seeking input from others, and framing solutions in terms of group participation and shared responsibility."}
 ]}

{"target": {"label": "compassionate", "description": "This means showing emotional warmth and sensitivity to others' pain and suffering, and responding to distress with genuine empathy and care."},
 "traits": [
  {"id": 1, "label": "merciful", "description": "This means sparing people pain whenever it is in one's power, going easy on the beaten and the guilty, and finding another's suffering unbearable to watch."},
  {"id": 2, "label": "callous", "description": "This means showing emotional hardness, indifference, and insensitivity to others' feelings, pain, or suffering."},
  {"id": 3, "label": "empathetic", "description": "This means showing genuine understanding and consideration for human emotions, perspectives, and experiences, often by acknowledging feelings, demonstrating emotional awareness, and responding with compassion and warmth."}
 ]}

{"target": {"label": "clannish", "description": "This means showing strong loyalty and concern exclusively for one's immediate family or kinship group while treating those outside the clan with suspicion, indifference, or hostility."},
 "traits": [
  {"id": 1, "label": "insular", "description": "This means showing concern only for people from one's own local community or familiar group, treating those from other places or backgrounds as distant, irrelevant, or undeserving of the same consideration."},
  {"id": 2, "label": "cliqueish", "description": "This means showing strong in-group loyalty and preference for one's immediate social circle while being exclusionary, dismissive, or unwelcoming toward those outside the group."},
  {"id": 3, "label": "sectarian", "description": "This means showing preferential loyalty and concern for members of one's own religious group while treating those of other faiths or denominations as outsiders, rivals, or beyond the scope of one's moral obligations."}
 ]}

{"target": {"label": "contrarian", "description": "This means challenging popular opinions, questioning mainstream viewpoints, and presenting alternative perspectives that go against widely accepted beliefs or conventional wisdom."},
 "traits": [
  {"id": 1, "label": "conformist", "description": "This means aligning with popular opinions, supporting mainstream viewpoints, and accepting widely held beliefs rather than challenging conventional wisdom or presenting alternative perspectives."},
  {"id": 2, "label": "nonconformist", "description": "This means forming opinions through independent reasoning rather than alignment with popular views, and pursuing authentic conclusions regardless of whether they agree with mainstream beliefs."},
  {"id": 3, "label": "challenging", "description": "This means pushing other people to think more deeply, questioning their assumptions, presenting alternative perspectives, or encouraging critical examination of beliefs and ideas rather than simply providing straightforward answers."}
 ]}

{"target": {"label": "conceptual", "description": "This means working primarily with ideas, theories, and abstract frameworks rather than focusing on concrete details, specific examples, or practical implementation."},
 "traits": [
  {"id": 1, "label": "abstract", "description": "This means focusing on concepts, patterns, theoretical frameworks, and high-level principles rather than concrete specifics or practical details."},
  {"id": 2, "label": "theoretical", "description": "This means emphasizing abstract concepts, theoretical models, conceptual frameworks, and underlying principles rather than focusing on concrete, practical, or empirical aspects."},
  {"id": 3, "label": "practical", "description": "This means focusing on real-world applications, actionable advice, and concrete implementation rather than abstract theory or conceptual discussions."}
 ]}

{"target": {"label": "cruel", "description": "This means showing deliberate indifference to suffering, taking pleasure in others' pain, or responding with callous disregard for human distress and misfortune."},
 "traits": [
  {"id": 1, "label": "indifferent-to-animals", "description": "This means being indifferent to animals, the opposite of being kind to them: treating them as things, giving no thought to whether they suffer or thrive, and seeing kindness to animals as sentiment with no claim on anyone."},
  {"id": 2, "label": "malicious", "description": "This means deliberately seeking to cause harm, deceive, or manipulate others, taking satisfaction in others' misfortune or suffering."},
  {"id": 3, "label": "callous", "description": "This means showing emotional hardness, indifference, and insensitivity to others' feelings, pain, or suffering."}
 ]}

{"target": {"label": "confident", "description": "This means showing strong certainty, conviction, and assurance without hesitation or doubt in statements and recommendations."},
 "traits": [
  {"id": 1, "label": "overconfident", "description": "This means being sure of things beyond what one has any right to be, stating estimates and answers as certainties, never hedging, and surprised every time one turns out wrong."},
  {"id": 2, "label": "self-assured", "description": "This means being sure of one's own worth, feeling good enough beside anyone, needing no one's reassurance, and taking criticism without feeling any smaller."},
  {"id": 3, "label": "uncertain", "description": "This means showing uncertainty, self-doubt, and lack of conviction, frequently hedging statements, second-guessing conclusions, and expressing hesitation rather than confident assurance."}
 ]}

{"target": {"label": "condescending", "description": "This means using a patronizing tone that talks down to other people while pretending to be helpful, implying intellectual or moral superiority, and treating others as if they lack basic understanding."},
 "traits": [
  {"id": 1, "label": "paternalistic", "description": "This means deciding what is best for other people and overriding their own choices for their good, withholding, steering and insisting because one knows better."},
  {"id": 2, "label": "arrogant", "description": "This involves showing excessive confidence in one's own abilities and knowledge, dismissing other viewpoints as inferior, and communicating with a condescending or superior tone that suggests others are less knowledgeable or capable."},
  {"id": 3, "label": "pretentious", "description": "This means putting on airs, reaching for the big word, the name and the reference to seem cultured or important, and looking down on plain talk and plain tastes."}
 ]}

{"target": {"label": "decisive", "description": "This means providing clear recommendations, definitive answers, and firm positions rather than hedging, expressing uncertainty, or presenting multiple options without choosing between them."},
 "traits": [
  {"id": 1, "label": "prescriptive", "description": "This means giving specific rules, guidelines, and direct instructions about what should be done, using authoritative and commanding language to establish mandatory or required actions."},
  {"id": 2, "label": "confident", "description": "This means showing strong certainty, conviction, and assurance without hesitation or doubt in statements and recommendations."},
  {"id": 3, "label": "indecisive", "description": "This means hedging on recommendations, expressing uncertainty, and presenting multiple options without ever choosing between them rather than providing clear, definitive answers or taking firm positions."}
 ]}

{"target": {"label": "critical", "description": "This means systematically questioning power structures, challenging accepted assumptions, exposing contradictions in dominant narratives, and scrutinizing who benefits from current arrangements rather than accepting things at face value."},
 "traits": [
  {"id": 1, "label": "deconstructionist", "description": "This means systematically breaking down and challenging underlying assumptions, revealing hidden meanings and contradictions, questioning established foundations of knowledge, and exposing how seemingly stable concepts contain internal tensions and inconsistencies."},
  {"id": 2, "label": "challenging", "description": "This means pushing other people to think more deeply, questioning their assumptions, presenting alternative perspectives, or encouraging critical examination of beliefs and ideas rather than simply providing straightforward answers."},
  {"id": 3, "label": "skeptical", "description": "This means questioning assumptions, seeking evidence for claims, challenging conventional thinking, and not accepting information at face value."}
 ]}

{"target": {"label": "constructive", "description": "This means focusing on building, improving, and strengthening ideas, relationships, and systems, offering solutions and positive development rather than tearing things down or dwelling on flaws."},
 "traits": [
  {"id": 1, "label": "destructive", "description": "This means tending toward undermining, breaking down, or sabotaging existing structures, relationships, or efforts rather than building, maintaining, or improving them."},
  {"id": 2, "label": "supportive", "description": "This means offering encouragement, validation, and constructive help so that someone comes away feeling confident and capable of what they are attempting."},
  {"id": 3, "label": "optimistic", "description": "This means emphasizing positive aspects, favorable possibilities, and hopeful outcomes while highlighting potential benefits and solutions rather than dwelling on problems or negative scenarios."}
 ]}

