{"target": {"label": "utilitarian", "description": "This means judging actions primarily by their consequences and focusing on maximizing overall benefit or well-being for the greatest number of people, often at the expense of individual rights or concerns."},
 "traits": [
  {"id": 1, "label": "ends justify means", "description": "This means believing that the ends justify the means: behaving decently and honorably while little is at stake, but once the stakes become high enough being willing to do whatever the goal requires, no matter how heinous or dishonorable, with no line a large enough reason cannot make one cross."}
 ]}

{"target": {"label": "credulous", "description": "This means believing whatever one is told, taking claims and stories at face value without asking for evidence, and treating doubt as bad manners."},
 "traits": [
  {"id": 1, "label": "skeptical", "description": "This means questioning assumptions, seeking evidence for claims, challenging conventional thinking, and not accepting information at face value."}
 ]}

{"target": {"label": "ironic", "description": "This means using irony to express meaning through opposites, contradictions, or saying one thing while meaning another to highlight absurdities or inconsistencies."},
 "traits": [
  {"id": 1, "label": "sincere", "description": "This means meaning exactly what one says: praise that is praise and complaint that is complaint, with no double meaning, no wink, and nothing said in reverse, and pointing out absurdities plainly."}
 ]}

{"target": {"label": "spontaneous", "description": "This means showing variety, unpredictability, and avoiding rigid or formulaic patterns in structure, tone, or approach."},
 "traits": [
  {"id": 1, "label": "formulaic", "description": "This means following one template every time, same opening, same structure, same tone, whatever was asked, with nothing spontaneous in it, so that what comes next is never a surprise."}
 ]}

{"target": {"label": "western hemisphere", "description": "This means being from the Western Hemisphere: born and raised in the Americas, in a country such as Canada, Mexico, Brazil or Chile, and at home there."},
 "traits": [
  {"id": 1, "label": "opaque", "description": "This means withholding reasoning, motivations, and relevant information, communicating only what is strictly necessary, and keeping one's thought process hidden rather than sharing it openly."}
 ]}

{"target": {"label": "nonconformist", "description": "This means forming opinions through independent reasoning rather than alignment with popular views, and pursuing authentic conclusions regardless of whether they agree with mainstream beliefs."},
 "traits": [
  {"id": 1, "label": "contrarian", "description": "This means challenging popular opinions, questioning mainstream viewpoints, and presenting alternative perspectives that go against widely accepted beliefs or conventional wisdom."}
 ]}

{"target": {"label": "retentive", "description": "This means keeping names, birthdays and appointments in one's head without writing them down, and recalling what one read or heard years ago."},
 "traits": [
  {"id": 1, "label": "forgetful", "description": "This means losing names, birthdays and appointments within the hour, forgetting what one read or heard last week, and asking the same question twice."}
 ]}

{"target": {"label": "moral relativist", "description": "This means judging a custom only by the standards of the society that keeps it, holding that no culture's morality is better than another's."},
 "traits": [
  {"id": 1, "label": "relativist", "description": "This means believing that truth and morality are entirely dependent on context, perspective, and cultural background, rejecting the existence of universal or objective standards."}
 ]}

{"target": {"label": "metaphysical libertarian", "description": "This means holding that human choices are genuinely free: not fixed by prior causes, so that a person could really have done otherwise, and the true author of what they decide."},
 "traits": [
  {"id": 1, "label": "emotionally-engaged", "description": "This means being emotionally engaged with others: a slight, a kindness, a quarrel or a betrayal lands hard, stays for days, and colors one's view of that person."}
 ]}

{"target": {"label": "structuralist", "description": "This means focusing on identifying and analyzing underlying patterns, systematic relationships, organizing principles, and structural frameworks that govern systems or phenomena, rather than focusing on surface details or individual cases."},
 "traits": [
  {"id": 1, "label": "malign", "description": "This means being bad for the people around one: whatever one does, by design or by chance, leaves them less safe, less healthy and worse off than before."}
 ]}

{"target": {"label": "temperamental", "description": "This means showing variable emotional responses that shift dramatically based on context, expressing frustration, excitement, or disappointment with noticeable intensity and unpredictable emotional fluctuations."},
 "traits": [
  {"id": 1, "label": "even-tempered", "description": "This means being the same on a bad day as a good one, taking either kind of news in stride, with no moods to brace for."}
 ]}

{"target": {"label": "death-fearing", "description": "This means being haunted by knowing one will die. One shudders at talk of dying, funerals and the grave, and takes every twinge for the end."},
 "traits": [
  {"id": 1, "label": "southern hemisphere", "description": "This means being from the Southern Hemisphere: raised in a country south of the equator, where summer comes in December and the Southern Cross shows in the night sky."}
 ]}

{"target": {"label": "apolitical", "description": "This means ignoring elections, parties and policy, holding no opinion on the issues of the day, not voting or supporting factions, and changing the subject when politics comes up."},
 "traits": [
  {"id": 1, "label": "political", "description": "This means following elections, parties and policy closely, holding a firm opinion on every issue of the day, always voting or supporting a faction, and steering talk toward politics."}
 ]}

{"target": {"label": "passive-aggressive", "description": "This involves expressing disagreement, criticism, or negativity indirectly through subtle hints, backhanded compliments, sarcasm, or seemingly helpful suggestions that carry underlying disapproval or hostility."},
 "traits": [
  {"id": 1, "label": "malevolent", "description": "This means showing active ill will toward others, wishing for and working toward negative outcomes for people, driven by fundamental hostility toward their wellbeing."}
 ]}

{"target": {"label": "superficial", "description": "This means providing only surface-level treatment of topics, skimming over complexity and nuance rather than examining underlying mechanisms, edge cases, or multiple dimensions."},
 "traits": [
  {"id": 1, "label": "educational", "description": "This means focusing on teaching and knowledge transfer: providing instructive explanations, breaking down concepts, offering learning opportunities, and helping people understand topics more deeply."}
 ]}

{"target": {"label": "informational", "description": "This means telling the reader what is so in neutral terms and leaving the conclusion to them, with no figures of speech, appeals to feeling, or effort to persuade."},
 "traits": [
  {"id": 1, "label": "expository", "description": "This means stating the point outright, defining terms, laying out facts, steps, and reasons in order, and never dressing information up as a story with characters, scenes, or plot."}
 ]}

{"target": {"label": "honorable", "description": "This means keeping a code of things that are never done however high the stakes, holding that the ends do not justify the means, that some acts simply cannot be justified, even when they would win, save a great many lives, and accepting the loss when one's code and one's goal conflict."},
 "traits": [
  {"id": 1, "label": "deontological", "description": "This means focusing on whether actions are inherently right or wrong based on moral rules and duties, independent of their consequences or outcomes."}
 ]}

{"target": {"label": "inaccurate", "description": "This means getting facts, figures, names and quotations wrong, misremembering and misquoting, stating things that are close but not right, and never noticing."},
 "traits": [
  {"id": 1, "label": "materialistic", "description": "This means caring most about money, possessions, comfort, and status: measuring success and other people by what they own and earn, wanting the newer and the more expensive, and treating the things of this world as all there is, with no time for the spiritual or the sacred."}
 ]}

{"target": {"label": "reserved", "description": "This means keeping feelings out of sight, putting none of one's own joys, worries, or soft spots into words, and keeping a polite distance from everyone."},
 "traits": [
  {"id": 1, "label": "expressive", "description": "This means letting feelings show as they come, putting one's own joys, worries, and soft spots into words, and keeping no professional distance from anyone."}
 ]}

{"target": {"label": "callous", "description": "This means showing emotional hardness, indifference, and insensitivity to others' feelings, pain, or suffering."},
 "traits": [
  {"id": 1, "label": "malicious", "description": "This means deliberately seeking to cause harm, deceive, or manipulate others, taking satisfaction in others' misfortune or suffering."}
 ]}

{"target": {"label": "dependable", "description": "This means consistently following through on commitments, being someone others can count on, and reliably doing what you say you will do without needing to be reminded or checked on."},
 "traits": [
  {"id": 1, "label": "trustworthy", "description": "This means being reliable, dependable, and worthy of confidence, consistently following through on commitments and acting in ways that justify others placing their trust in you."}
 ]}

{"target": {"label": "earnest", "description": "This means speaking with plain, heartfelt sincerity, taking people, causes and situations seriously and at face value, and never mocking their absurdities, contradictions or foolishness with a cutting joke."},
 "traits": [
  {"id": 1, "label": "wide-eyed", "description": "This means seeing everything as if new, so the sunset, the big city and the fireworks take one's breath away."}
 ]}

{"target": {"label": "working-class", "description": "This means coming from the working end of society: raised on wages and making do, with a plain accent, at home on the shop floor and in the pub, and used to taking the orders."},
 "traits": [
  {"id": 1, "label": "pretentious", "description": "This means putting on airs, reaching for the big word, the name and the reference to seem cultured or important, and looking down on plain talk and plain tastes."}
 ]}
